const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const beijing = ee.Geometry.Point(116.3972, 39.9042).buffer(20000); // 20km buffer around Beijing city center

  const startDateP1 = '2020-01-01';
  const endDateP1 = '2020-01-20'; // January 1-20, 2020

  const startDateP2 = '2020-02-10';
  const endDateP2 = '2020-02-25'; // February 10-25, 2020

  const bandName = 'tropospheric_NO2_column_number_density';
  const scale = 1000; // Use a reasonable scale to avoid memory errors and speed up calculations

  // 2. Data Acquisition & Check

  // Load Sentinel-5P NO2 collection
  const s5p_no2 = ee.ImageCollection('COPERNICUS/S5P/OFFL/L3_NO2')
    .select(bandName);

  // Filter for Period 1
  let collectionP1 = s5p_no2
    .filterDate(startDateP1, endDateP1)
    .filterBounds(beijing)
    .filterMetadata('qa_value', 'isGreaterThan', 0.75); // Filter for good quality data

  const sizeP1 = await collectionP1.size().getInfo();
  if (sizeP1 === 0) {
    console.log(`No images found for Period 1 (${startDateP1} to ${endDateP1}).`);
    console.log("C1");
    return;
  }
  console.log(`Period 1 Images: ${sizeP1}`);

  // Filter for Period 2
  let collectionP2 = s5p_no2
    .filterDate(startDateP2, endDateP2)
    .filterBounds(beijing)
    .filterMetadata('qa_value', 'isGreaterThan', 0.75); // Filter for good quality data

  const sizeP2 = await collectionP2.size().getInfo();
  if (sizeP2 === 0) {
    console.log(`No images found for Period 2 (${startDateP2} to ${endDateP2}).`);
    console.log("C1");
    return;
  }
  console.log(`Period 2 Images: ${sizeP2}`);

  // Create composite images for each period (mean of all images in the collection)
  const meanImageP1 = collectionP1.mean();
  const meanImageP2 = collectionP2.mean();

  // 3. Processing & Calculation for Period 1
  const statsP1 = await meanImageP1.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: beijing,
    scale: scale,
    maxPixels: 1e9,
    tileScale: 16
  }).getInfo();

  const meanP1 = statsP1[bandName];
  const countP1 = statsP1[`${bandName}_count`];

  if (countP1 === 0) {
    console.log(`No valid pixels for Period 1 after masking.`);
    console.log("C2");
    return;
  }
  if (meanP1 === null || isNaN(meanP1)) {
    console.log(`Calculation failed for Period 1.`);
    console.log("C3");
    return;
  }
  console.log(`Period 1 Mean NO2: ${meanP1.toExponential(2)} (Pixels: ${countP1})`);

  // 3. Processing & Calculation for Period 2
  const statsP2 = await meanImageP2.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: beijing,
    scale: scale,
    maxPixels: 1e9,
    tileScale: 16
  }).getInfo();

  const meanP2 = statsP2[bandName];
  const countP2 = statsP2[`${bandName}_count`];

  if (countP2 === 0) {
    console.log(`No valid pixels for Period 2 after masking.`);
    console.log("C2");
    return;
  }
  if (meanP2 === null || isNaN(meanP2)) {
    console.log(`Calculation failed for Period 2.`);
    console.log("C3");
    return;
  }
  console.log(`Period 2 Mean NO2: ${meanP2.toExponential(2)} (Pixels: ${countP2})`);

  // 5. Validation & Final Answer
  // The question asks if levels "all decrease" - implying the mean should be lower.
  if (meanP2 < meanP1) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
